"""Дополняет общий DOCX, сохраняя исходные разделы ПР 1–2 и поле TOC.

Запуск из корня проекта после формирования report-assets/pr3 и pr4.
Рендер и обновление кеша страниц выполняются отдельно check_report.py.
"""
from datetime import datetime, timezone
from pathlib import Path

from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Pt

ROOT=Path(__file__).resolve().parent.parent
PATH=ROOT/'docs/Отчет_Шустов_ЗН251.docx'
doc=Document(PATH)
# Убираем только разделы начиная с ПР 3, включая будущую библиографию/приложение.
start=next(p for p in doc.paragraphs if p.style.name=='Heading 1' and p.text.startswith('3 Практическая'))
body=doc._element.body
for element in list(body)[list(body).index(start._p):]:
    if element.tag!=qn('w:sectPr'):body.remove(element)
# Введение актуализируется; текст и XML разделов ПР 1–2 остаются прежними.
for p in doc.paragraphs:
    if p.text.startswith('Используются HTML5, CSS, JavaScript, Git'):
        p.text='Используются HTML5, CSS, JavaScript, Python, FastAPI, Jinja2 и SQLite. Для развёртывания применены Docker и существующий Nginx на VDS Debian 13; защищённое соединение обеспечивает сертификат Let’s Encrypt. Код хранится в Git, проверки выполняются pytest и Playwright.'
    if p.text.startswith('Отчёт содержит четыре раздела. Заполнены'):
        p.text='Отчёт содержит результаты четырёх практических работ. ПР 1 и ПР 2 сохранены как описание предыдущих этапов, ПР 3 и ПР 4 описывают приложение с базой данных и публикацию на собственном сервере. Требования к отчёту заданы правилами дисциплины [2]. Репозиторий и структура проекта приведены в приложении А.'


def p(text='',style='Report Body'):
    return doc.add_paragraph(text,style)


def heading(text,level=2):
    return doc.add_paragraph(text,f'Heading {level}')


def listing(title,code):
    cap=p(title);cap.paragraph_format.first_line_indent=Cm(0)
    block=p(code);block.alignment=WD_ALIGN_PARAGRAPH.LEFT;block.paragraph_format.first_line_indent=Cm(0)
    block.paragraph_format.line_spacing=1.15
    for run in block.runs:run.font.name='Courier New';run.font.size=Pt(12)
    block.paragraph_format.keep_together=True


def figure(path,caption,width=16.5):
    para=p();para.alignment=WD_ALIGN_PARAGRAPH.CENTER
    para.paragraph_format.first_line_indent=Cm(0)
    para.paragraph_format.keep_with_next=True
    para.add_run().add_picture(str(ROOT/'docs/report-assets'/path),width=Cm(width))
    cap=p(caption);cap.alignment=WD_ALIGN_PARAGRAPH.CENTER
    cap.paragraph_format.first_line_indent=Cm(0)
    cap.paragraph_format.keep_together=True


def table(caption,headers,rows):
    cap=p(caption);cap.paragraph_format.first_line_indent=Cm(0)
    cap.paragraph_format.keep_with_next=True
    t=doc.add_table(rows=1,cols=len(headers));t.style='Table Grid'
    for c,x in zip(t.rows[0].cells,headers):c.text=x
    repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for row in rows:
        for cell,x in zip(t.add_row().cells,row):cell.text=str(x)
    for row in t.rows:
        row._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
        for cell in row.cells:
            for para in cell.paragraphs:
                para.paragraph_format.first_line_indent=Cm(0)
                para.paragraph_format.line_spacing=1.15
                para.paragraph_format.space_after=Pt(3)
                for run in para.runs:run.font.name='Times New Roman';run.font.size=Pt(12);run.bold=False
    return t

